example:
订单备注组件：

```vue
<script setup>
import { ref } from "vue";
const memo = ref("");
</script>

<template>
  <label>
    备注
    <input v-model="memo" />
  </label>
  <p>{{ memo }}</p>
</template>
```

测试先挂载，再写入输入框：

```javascript
import { mount } from "@vue/test-utils";
import { expect, test } from "vitest";
import MemoNote from "./MemoNote.vue";

test("typing updates the memo", async () => {
  const wrapper = mount(MemoNote);
  await wrapper.get("input").setValue("补一笔");
  expect(wrapper.text()).toContain("补一笔");
});
```
